"""
Utils
"""
import datetime
import time
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.admin.other_admin_ops import OtherAdminOps


class DictQuery(dict):
    """
    DictQuery
    """
    def get(self, path, default="NOT FOUND"):
        """
        Function to get DictQuery
        """
        keys = path.split(".")
        val = None
        for key in keys:
            if val:
                if isinstance(val, list):
                    try:
                        val = val[int(key)]
                    except IndexError as e:
                        return "NOT FOUND"
                else:
                    val = val.get(key, default)
            else:
                val = dict.get(self, key, default)
            if not val:
                break
        return val


def _generate_scf(alias, timeout=120):
    tstamp = datetime.datetime.fromtimestamp(time.time()).strftime('%d%m%y_%H%M%S')
    target_file = 'execution_logs/{}'.format('scf_{}'.format(tstamp))
    OtherAdminOps().generate_scf(target_file=target_file, alias=alias, timeout=timeout)
    global_vars.alias_scf_dict[alias] = target_file
    return target_file
